#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int parse_long(const char *s, long *out) {
    char *end;
    if (s == NULL) return 0;
    long val = strtol(s, &end, 10);
    if (end == s) return 0;          // no conversion
    if (*end != '\0') return 0;     // extra characters
    *out = val;
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    long n, k;
    if (!parse_long(argv[1], &n) || !parse_long(argv[2], &k)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 1 || k < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (k > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long result = 0; // zero‑based survivor index
    for (long i = 2; i <= n; ++i) {
        result = (result + k) % i;
    }
    printf("%ld\n", result + 1);
    return 0;
}
